-- Seed the Liv Bona Dea Hospital doctors from the hospital's own public
-- directory (livhospital.az), so the directory is not empty on the day the
-- first person opens it.
--
-- None of these doctors asked to be here. That is the whole reason every row
-- below is UNCLAIMED with accepts_bookings = 0: the listing repeats what the
-- hospital already publishes, it does not assert that we checked anything, and
-- it cannot take an appointment nobody is watching. A doctor who claims their
-- listing goes to PENDING and is reviewed like any other claim.

INSERT INTO clinic (name, slug, address, city, phone, description, active, created_at, updated_at)
SELECT * FROM (SELECT
    'Liv Bona Dea Hospital' AS name,
    'liv-bona-dea-hospital' AS slug,
    'Ziya Bunyadov prospekti 2091, Baki' AS address,
    'Baki' AS city,
    '+994 12 525 09 00' AS phone,
    'Liv Bona Dea Hospital, Baki. Listing built from the hospital directory at livhospital.az.' AS description,
    1 AS active, NOW() AS created_at, NOW() AS updated_at) AS c
WHERE NOT EXISTS (SELECT 1 FROM clinic WHERE slug = 'liv-bona-dea-hospital');

SET @clinic_id = (SELECT id FROM clinic WHERE slug = 'liv-bona-dea-hospital');

-- INSERT IGNORE, not ON DUPLICATE KEY: MariaDB on production does not take
-- the row-alias form, and a slug that somehow already exists should be left
-- alone rather than overwritten by a scrape.
